export const extractAllIdentifiers = (item: any): Set<string> => {
  const ids = new Set<string>();
  if (!item) return ids;

  const data = item.originalData || item;

  [
    item.id,
    data.id,
    data._id,
    data.property_code,
    data.code,
    data.project_id,
    data.project_code,
    data.lead_number,
    data.customer_number,
    data.name
  ].forEach(val => {
    if (val && typeof val === 'string' && val.trim()) {
      const trimmed = val.trim();
      ids.add(trimmed);
      ids.add(trimmed.toLowerCase());
      ids.add(trimmed.toUpperCase());
    }
  });

  const titlesToProcess = [
    item.title,
    data.title,
    data.property_title,
    data.project_title,
    data.project_name,
    data.name
  ];

  titlesToProcess.forEach(rawTitle => {
    if (rawTitle && typeof rawTitle === 'string' && rawTitle.trim()) {
      const t = rawTitle.trim();
      ids.add(t.toLowerCase());
      const cleanT = t.replace(/\s*\([^)]*\)/g, '').trim().toLowerCase();
      if (cleanT) ids.add(cleanT);
      const match = t.match(/\(([^)]+)\)/);
      if (match && match[1]) {
        ids.add(match[1].trim().toLowerCase());
        ids.add(match[1].trim().toUpperCase());
      }
    }
  });

  return ids;
};

export const isItemInRecycledSet = (targetItem: any, recycledSet: Set<string>): boolean => {
  if (!targetItem || !recycledSet || recycledSet.size === 0) return false;
  const targetIds = extractAllIdentifiers(targetItem);
  for (const id of targetIds) {
    if (recycledSet.has(id)) return true;
  }
  return false;
};

export const cleanExecutiveName = (val?: string): string => {
  if (!val) return 'Avishek Das';
  const str = String(val).trim();
  return str.split(/\s+[—\-]\s+/)[0].trim();
};

export const numberToWordsIndian = (num: number): string => {
  if (isNaN(num) || num <= 0) return 'Rupees Zero Only';

  const units = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 
                 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
  const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

  const convertChunk = (n: number): string => {
    if (n === 0) return '';
    if (n < 20) return units[n];
    if (n < 100) return tens[Math.floor(n / 10)] + (n % 10 !== 0 ? ' ' + units[n % 10] : '');
    return units[Math.floor(n / 100)] + ' Hundred' + (n % 100 !== 0 ? ' ' + convertChunk(n % 100) : '');
  };

  const integerPart = Math.floor(Math.abs(num));
  if (integerPart === 0) return 'Rupees Zero Only';

  const crore = Math.floor(integerPart / 10000000);
  let remainder = integerPart % 10000000;
  const lakh = Math.floor(remainder / 100000);
  remainder = remainder % 100000;
  const thousand = Math.floor(remainder / 1000);
  remainder = remainder % 1000;
  const hundred = remainder;

  const parts: string[] = [];

  if (crore > 0) parts.push(`${convertChunk(crore)} Crore`);
  if (lakh > 0) parts.push(`${convertChunk(lakh)} Lakh`);
  if (thousand > 0) parts.push(`${convertChunk(thousand)} Thousand`);
  if (hundred > 0) parts.push(convertChunk(hundred));

  const words = parts.join(' ').trim();
  return words ? `Rupees ${words} Only` : 'Rupees Zero Only';
};

