  const handleOpenEditUserModal = (u: any) => {
    const isLoggedSuperAdmin = loggedInUser?.role === 'SUPER_ADMIN' || loggedInUser?.role === 'OWNER';
    const targetRole = (u?.role || '').toUpperCase();
    const isTargetAdminOrSuper = targetRole.includes('SUPER') || targetRole.includes('OWNER') || targetRole === 'ADMIN' || targetRole.includes('ADMIN');

    if (!isLoggedSuperAdmin && isTargetAdminOrSuper) {
      alert('🔒 Access Denied: Admin accounts cannot edit Admin or Super Admin profiles. Admins can only maintain staff profiles below Admin level. Super Admin maintains all profiles.');
      return;
    }

    setEditingUser(u);
    const foundMatrix = rolePermissions.find((r: any) => r.role_key === u.role || r.role_code === u.role);
    const userPerms = u.permissions || (foundMatrix ? {
      perm_view: !!foundMatrix.view,
      perm_create: !!foundMatrix.create,
      perm_edit: !!foundMatrix.edit,
      perm_delete: !!foundMatrix.delete,
      perm_export: !!foundMatrix.export,
      perm_approve: !!foundMatrix.approve,
      perm_price_change: !!foundMatrix.price_change,
      perm_brokerage: !!foundMatrix.brokerage
    } : { perm_view: true, perm_create: true, perm_edit: true, perm_delete: false, perm_export: true, perm_approve: false, perm_price_change: false, perm_brokerage: false });

    const currentBranch = u.branch_name && branches.some((b: any) => b.branch_name === u.branch_name)
      ? u.branch_name
      : (branches && branches.length > 0 ? branches[0].branch_name : 'Head Office (Kolkata)');

    const currentTeam = u.team_name && teams.some((t: any) => (t.team_name || t.name) === u.team_name)
      ? u.team_name
      : (teams && teams.length > 0 ? (teams[0].team_name || teams[0].name) : 'Corporate Leadership Squad');

    setNewUserForm({
      username: u.username || u.full_name,
      full_name: u.full_name,
      email: u.email,
      password: u.password || 'Swaramayi@2026',
      mobile: u.mobile,
      role: u.role,
      designation: u.designation || '',
      branch_name: currentBranch,
      department: u.department || 'Executive Board',
      team_name: currentTeam,
      manager_name: u.manager_name || 'Avishek Das (Super Admin)',
      permissions: userPerms
    });
    setShowUserModalPassword(false);
    setShowUserModal(true);
  };

