                                    <td style={{ padding: '10px', fontWeight: '800', color: isLight ? '#0f172a' : '#ffffff' }}>
                                      {c.name} <span style={{ fontSize: '0.7rem', color: isLight ? '#64748b' : '#94a3b8', fontWeight: '400' }}>({c.phone || c.mobile || 'N/A'})</span>
                                    </td>
